  // Mirrors the thread‑creation loop from startSession / startThreadsForExistingSession
  for (const agentId of agentIds) {
    this.ensureAgentState(agentId);
    if (!this.agentConfigs.has(agentId)) {
      // Preserve the original config (model/effort/persona) if present in the snapshot
      const cfg = this.agentConfigs.get(agentId);
      const agentCfg = this.agentConfigs.get(agentId) ?? { id: agentId, name: "Agent" };
      this.agentConfigs.set(agentId, { id: agentId, name: agentCfg?.name ?? "Agent", model: agentCfg?.model, effort: agentCfg?.effort });
    }
